-- ============================================================
-- Sistem Reservasi Hotel & Homestay - PHP Native + MySQL
-- Import lewat phpMyAdmin atau:  mysql -u root -p < database/reservasi_hotel.sql
-- ============================================================

CREATE DATABASE IF NOT EXISTS reservasi_hotel CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE reservasi_hotel;

DROP TABLE IF EXISTS layanan;
DROP TABLE IF EXISTS reservasi;
DROP TABLE IF EXISTS tamu;
DROP TABLE IF EXISTS kamar;
DROP TABLE IF EXISTS tipe_kamar;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS pengaturan;

CREATE TABLE pengaturan (
  id INT PRIMARY KEY,
  nama_hotel VARCHAR(100) NOT NULL,
  alamat VARCHAR(255),
  telepon VARCHAR(30),
  jam_checkin VARCHAR(5) NOT NULL DEFAULT '14:00',
  jam_checkout VARCHAR(5) NOT NULL DEFAULT '12:00',
  pajak_persen TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  username VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  role ENUM('admin','resepsionis') NOT NULL DEFAULT 'resepsionis',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE tipe_kamar (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(60) NOT NULL,
  harga INT NOT NULL,
  kapasitas TINYINT NOT NULL DEFAULT 2,
  fasilitas VARCHAR(255)
) ENGINE=InnoDB;

CREATE TABLE kamar (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nomor VARCHAR(10) NOT NULL UNIQUE,
  lantai TINYINT NOT NULL DEFAULT 1,
  tipe_id INT NOT NULL,
  status ENUM('tersedia','terisi','kotor','perbaikan') NOT NULL DEFAULT 'tersedia',
  FOREIGN KEY (tipe_id) REFERENCES tipe_kamar(id)
) ENGINE=InnoDB;

CREATE TABLE tamu (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  identitas VARCHAR(30),          -- NIK / paspor
  telepon VARCHAR(20) NOT NULL,
  email VARCHAR(100),
  kota VARCHAR(60),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE reservasi (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kode VARCHAR(20) NOT NULL UNIQUE,
  tamu_id INT NOT NULL,
  kamar_id INT NOT NULL,
  check_in DATE NOT NULL,
  check_out DATE NOT NULL,
  malam SMALLINT NOT NULL,
  dewasa TINYINT NOT NULL DEFAULT 2,
  harga_malam INT NOT NULL,          -- snapshot harga saat booking
  diskon INT NOT NULL DEFAULT 0,
  dibayar INT NOT NULL DEFAULT 0,
  sumber ENUM('Walk-in','Telepon/WA','Website','OTA') NOT NULL DEFAULT 'Walk-in',
  status ENUM('booking','checkin','checkout','batal') NOT NULL DEFAULT 'booking',
  catatan VARCHAR(255),
  user_id INT NULL,
  checkin_at DATETIME NULL,
  checkout_at DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_kamar_tgl (kamar_id, check_in, check_out),
  FOREIGN KEY (tamu_id) REFERENCES tamu(id),
  FOREIGN KEY (kamar_id) REFERENCES kamar(id),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- Tagihan tambahan selama menginap (laundry, makan, extra bed, dll.)
CREATE TABLE layanan (
  id INT AUTO_INCREMENT PRIMARY KEY,
  reservasi_id INT NOT NULL,
  nama VARCHAR(100) NOT NULL,
  qty INT NOT NULL DEFAULT 1,
  harga INT NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (reservasi_id) REFERENCES reservasi(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Password kedua akun: admin123



-- Reservasi yang sudah check-out dianggap lunas termasuk layanan tambahan
UPDATE reservasi r SET dibayar = malam * harga_malam - diskon + (SELECT COALESCE(SUM(qty*harga),0) FROM layanan l WHERE l.reservasi_id = r.id) WHERE status = 'checkout';
SET @n := 0;
UPDATE reservasi SET kode = CONCAT('RSV-', DATE_FORMAT(created_at, '%y%m'), '-', LPAD(@n := @n + 1, 4, '0')) ORDER BY created_at, id;
-- Status kamar mengikuti tamu yang sedang menginap; 2 kamar contoh perlu dibersihkan / perbaikan
UPDATE kamar k SET status = 'terisi' WHERE EXISTS (SELECT 1 FROM reservasi r WHERE r.kamar_id = k.id AND r.status = 'checkin');
UPDATE kamar SET status = 'kotor' WHERE status = 'tersedia' ORDER BY id LIMIT 2;
UPDATE kamar SET status = 'perbaikan' WHERE nomor = '206' AND status <> 'terisi';

-- Pastikan hari ini ada contoh tamu pulang & tamu datang (tanpa menimbulkan bentrok)
UPDATE reservasi r JOIN (SELECT id FROM reservasi WHERE status = 'checkin' AND check_out = CURDATE() + INTERVAL 1 DAY AND malam > 1 ORDER BY id LIMIT 3) x ON x.id = r.id
SET r.check_out = CURDATE(), r.malam = r.malam - 1;
UPDATE reservasi r JOIN (
    SELECT a.id FROM reservasi a WHERE a.status = 'booking' AND a.check_in = CURDATE() + INTERVAL 1 DAY
    AND NOT EXISTS (SELECT 1 FROM reservasi b WHERE b.kamar_id = a.kamar_id AND b.id <> a.id AND b.status IN ('booking','checkin') AND b.check_in < CURDATE() + INTERVAL 1 DAY AND b.check_out > CURDATE())
    ORDER BY a.id LIMIT 3) x ON x.id = r.id
SET r.check_in = CURDATE(), r.malam = r.malam + 1;
